CREATE OR REPLACE SQL SECURITY INVOKER VIEW `v_alerta_semantica` AS
select `a`.`id_alert` AS `id_alert`,`a`.`date` AS `inicio_epoch`,from_unixtime(`a`.`date`) AS `inicio`,`a`.`severity` AS `severidad`,`a`.`type` AS `origen`,`a`.`label` AS `texto`,`a`.`event_data` AS `event_data`,`a`.`id_device` AS `iddev`,`a`.`name` AS `dispositivo`,`a`.`ip` AS `ip`,`a`.`id_metric` AS `idmetric`,`a`.`subtype` AS `subtype`,`i`.`instance_id` AS `instance_id`,`i`.`stable_key` AS `instancia`,(case when (`cc`.`canonical_id` in ('net.icmp.latency','net.icmp.availability')) then 'net.icmp.availability' else `cc`.`canonical_id` end) AS `concepto`,(case when (`cc`.`canonical_id` in ('net.icmp.latency','net.icmp.availability')) then 'Disponibilidad ICMP' else `cc`.`display_name` end) AS `que_mide`,`cc`.`unit` AS `unidad`,`cc`.`direction` AS `direccion`,`cc`.`signal_class` AS `clase`,`br`.`role_id` AS `rol`,`r`.`display_name` AS `rol_nombre`,`r`.`role_type` AS `rol_tipo`,`r`.`criticality` AS `criticidad`,`br`.`is_primary` AS `es_primaria`,`br`.`weight` AS `peso`,(case when (`cc`.`canonical_id` in ('net.icmp.latency','net.icmp.availability')) then concat('dev:',`a`.`id_device`,':icmp') else concat('inst:',`i`.`instance_id`) end) AS `senal_id` from ((((((`alerts` `a` left join `sem_metric_binding` `mb` on(((`mb`.`idmetric` = `a`.`id_metric`) and (`mb`.`status` = 'active')))) left join `sem_instance` `i` on((`i`.`instance_id` = `mb`.`instance_id`))) left join `sem_metric_concept` `mc` on((`mc`.`subtype` = `i`.`subtype`))) left join `sem_canonical_concept` `cc` on((`cc`.`canonical_id` = coalesce(`i`.`canonical_override`,`mc`.`canonical_id`)))) left join `sem_binding_role` `br` on(((`br`.`instance_id` = `i`.`instance_id`) and (`br`.`status` = 'active')))) left join `sem_business_role` `r` on((`r`.`role_id` = `br`.`role_id`))) where ((`a`.`type` in ('snmp','latency','xagent')) and (`a`.`severity` <> 4));
